from collections import Counter
def transform(g):
    H,W=len(g),len(g[0])
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    rest=[c for c in cnt if c!=bg]
    # marker color: forms two straight bars (more cells); ink: fewer cells
    marker=min(rest,key=lambda c:cnt[c]) if len(rest)==2 else None
    inkc=[c for c in rest if c!=marker][0]
    ink=[(r,c) for r in range(H) for c in range(W) if g[r][c]==inkc]
    k=len(ink)
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]==marker]
    # split into two bars: cluster by connected line
    rs=sorted(set(r for r,c in cells)); cs=sorted(set(c for r,c in cells))
    if len(rs)<len(cs):  # vertical bars (one column each)
        bars=[]
        colsv=sorted(set(c for r,c in cells))
        for col in colsv:
            b=sorted(r for r,c in cells if c==col); bars.append(('V',col,b))
    else:
        for row in sorted(set(r for r,c in cells)):
            b=sorted(c for r,c in cells if r==row); bars.append(('H',row,b))
    out=[row[:] for row in g]
    def shoot(r,c,dr,dc):
        rr,cc=r+dr,c+dc
        while 0<=rr<H and 0<=cc<W:
            if out[rr][cc]==inkc:
                out[rr][cc]=4; return
            out[rr][cc]=inkc; rr+=dr; cc+=dc
    for i,(o,b) in enumerate(bars):
        other=bars[1-i]
        if o=='V':
            col,rows=b
            dr=1 if other[1]>col else -1  # toward other bar column
            for r in rows[:k]: shoot(r,col,0,dr)
        else:
            row,cols=b
            dc=1 if other[1]>row else -1  # toward other bar row
            for c in cols[:k]: shoot(row,c,dc,0)
    return out

